{
  "id": "SPEC-VERSIONING",
  "purpose": "Define how `callisto version`, `pre` and `snapshot` turn pending changesets and commits into new package versions, dependency rewrites, changelog sections and an optional release decision file.",
  "scope": "Changeset file format, severity aggregation and commit inference, dependency cascade, fixed and linked groups, prerelease and snapshot versions, and applying the plan to disk.",
  "non_goals": [
    "Creating changesets interactively with `callisto add`.",
    "Publishing, tagging, and verifying a committed release decision during `release`.",
    "Package discovery, workspace config parsing and dependency graph construction.",
    "Release PR body composition."
  ],
  "api_surface": [
    {
      "name": "callisto version",
      "signature": "callisto version [--strict] [--allow-empty-changesets] [--no-refresh-lockfiles] [--emit-decision <PATH>] [--dry-run]",
      "description": "Computes the version plan from pending changesets, inference, cascade and groups, then applies it to disk and stages it in git."
    },
    {
      "name": "callisto pre",
      "signature": "callisto pre enter <TAG> | callisto pre exit",
      "description": "Enters or exits prerelease mode by writing `.changeset/pre.json`."
    },
    {
      "name": "callisto snapshot",
      "signature": "callisto snapshot --tag <TAG> [--strict] [--dry-run]",
      "description": "Sets every package to a throwaway native-grammar snapshot version without consuming changesets: `0.0.0-{tag}-{sha7}` for SemVer and `0.0.0.dev0+{tag}.{sha7}` for PEP 440."
    }
  ],
  "acceptance_criteria": [
    {
      "id": "VER-CS-01",
      "criterion": "A changeset is a Markdown file whose line 1 is `---`, followed by one `name: severity` entry per line, a closing `---` line and a free-text summary; blank lines and lines starting with `#` inside the frontmatter are ignored. Severities are `major`, `minor`, `patch` and `none` (ordered none < patch < minor < major), read case-insensitively and written lowercase."
    },
    {
      "id": "VER-CS-02",
      "criterion": "A package name may be double-quoted, and a quoted name may contain `:` (`\"maven/org.example:foo-core\": major` parses as that name with severity major); an unquoted name is split at its last `:`."
    },
    {
      "id": "VER-CS-03",
      "criterion": "A leading UTF-8 BOM is ignored, CRLF and CR line endings parse the same as LF, the summary is trimmed of surrounding whitespace, and a changeset with a summary but no entries is valid."
    },
    {
      "id": "VER-CS-04",
      "criterion": "Parsing fails with E040 when line 1 is not `---`, E041 when the frontmatter is never closed, and E055 when there are entries but the summary is empty or whitespace-only. A changeset with no entries and no summary (the shape `@changesets/cli add --empty` writes) parses as a valid, empty changeset.",
      "is_error_case": true
    },
    {
      "id": "VER-CS-05",
      "criterion": "Parsing fails on a bad entry line and reports its line number: unclosed quoted name (E042), text between a quoted name and its `:` (E043), no `:` (E044), empty name (E045), unknown severity (E046), or a name already used in the same file (E047, also citing the first line).",
      "is_error_case": true
    },
    {
      "id": "VER-CS-06",
      "criterion": "Writing a changeset emits `---`, one `name: severity` line per entry in order, `---`, a blank line, the trimmed summary and a trailing newline; a name is quoted when it starts with a YAML-significant character (such as `@`, `-`, `#`, `\"` or a space), contains `:` or `#`, or ends with a space."
    },
    {
      "id": "VER-CS-07",
      "criterion": "Writing fails for an empty summary (E049 with no entries, E056 with entries), an empty package name (E057), or a name containing `\"`.",
      "is_error_case": true
    },
    {
      "id": "VER-CS-08",
      "criterion": "`version` reads every `.md` file directly inside the configured changesets directory (default `.changeset`) except `README.md`, in path order; a missing directory means no changesets, and one unparsable file aborts the run with an error naming that file.",
      "is_error_case": true
    },
    {
      "id": "VER-AGG-01",
      "criterion": "A package's severity is the highest severity among all changeset entries naming it and its inferred severity."
    },
    {
      "id": "VER-AGG-02",
      "criterion": "An entry name resolves to a workspace package by prefixed id (`cargo/foo`) or bare name; a bare name that matches packages in two or more ecosystems aborts the run with an ambiguous-name error (E103).",
      "is_error_case": true
    },
    {
      "id": "VER-AGG-03",
      "criterion": "An entry naming a package not in the workspace, or an invalid name, produces an unknown-package warning, and a changeset with any such unresolved entry stays on disk unconsumed, even when its other entries resolve. An entry with severity `none` causes no bump and no changelog line, but its changeset is still consumed."
    },
    {
      "id": "VER-AGG-04",
      "criterion": "Commit inference runs only for packages with `release-trigger = \"auto\"`; packages with the default `release-trigger = \"changeset\"` take severity from changesets alone. Inference reads conventional commits touching the package's directory since its last release tag (all history when untagged): a `!` marker or `BREAKING CHANGE`/`BREAKING-CHANGE` footer maps to major, `feat` to minor, `fix`/`perf`/`revert` to patch, anything else to none."
    },
    {
      "id": "VER-AGG-05",
      "criterion": "`pre-major-inference` changes only inferred severity, and only for a package with a prior release tag whose current version is `0.y.z` with y >= 1: `conservative` maps major to minor, `conservative-feat` also maps minor to patch, and `off` (default) changes nothing."
    },
    {
      "id": "VER-AGG-06",
      "criterion": "When no changeset is consumed, `version` warns \"No pending changesets found in workspace\" unless `--allow-empty-changesets` or `[validation] allow-empty-changesets = true` is set; with `--strict` the warning is an error and `version` exits with a failure status.",
      "is_error_case": true
    },
    {
      "id": "VER-CAS-01",
      "criterion": "When a package is bumped, each dependent's spec on it is tested against the new version. Under `[cascade] mode = \"out-of-range\"` (default) a runtime, optional, build or peer dependent is bumped only when its spec no longer covers the new version; under `mode = \"always\"` it is bumped regardless. Coverage governs only the dependent's own severity bump; whether its spec is rewritten follows VER-CAS-06."
    },
    {
      "id": "VER-CAS-02",
      "criterion": "A cascaded bump has severity `bump-severity` (`patch` default, or `minor`), never lowers a severity the dependent already has, and propagates to that dependent's own dependents."
    },
    {
      "id": "VER-CAS-03",
      "criterion": "With `peer-escalation = true` (default), a peer dependent whose spec no longer covers a minor or major bump of its dependency receives a major bump; a patch bump of the dependency cascades at `bump-severity`."
    },
    {
      "id": "VER-CAS-04",
      "criterion": "A dev dependent is never bumped by the cascade, but its spec is still rewritten when it no longer covers the new version."
    },
    {
      "id": "VER-CAS-05",
      "criterion": "Coverage: an exact spec covers only the equal version, a bare Cargo version is a caret requirement, a caret requirement never covers a prerelease, a Cargo `workspace = true` spec is tested using the root `[workspace.dependencies]` spec, and an npm `workspace:` spec always covers. A catalog or other untestable spec is treated as covering and never rewritten; a catalog spec emits a CatalogSpecNotRewritten warning."
    },
    {
      "id": "VER-CAS-06",
      "criterion": "A spec that no longer covers the new version is rewritten to it, keeping the operator and precision for Cargo and npm (`^1.2` becomes `^2.0` for 2.0.0), or to the exact version for npm when `preserve-npm-ranges = false`. A runtime, optional, build or peer dependent that is itself released in this run, for any reason, has every such spec on a bumped internal dependency raised to the dependency's new version the same way, even when the spec still covers it; a dependent that is not releasing keeps its spec unless out of range. `workspace = true`, npm `workspace:` and catalog specs are never rewritten by either rule, and a dev dependent's spec is rewritten only when out of range. A spec that cannot be rewritten mechanically, such as an npm range with spaces, `||`, a hyphen or a wildcard, is left unchanged with a RangeNotRoundTrippable warning."
    },
    {
      "id": "VER-CAS-07",
      "criterion": "A rewrite uses the source declaration's manifest ecosystem and preserves its declared dependency key or spelling, independent of either package's display prefix. A Cargo dependency's `package` name resolves its native target while edits retain its alias; inherited aliases resolve the workspace root's declaration. Python distribution names match using PEP 503 normalization while edits retain the spelling in the dependency declaration. A Cargo dependency inherited with `workspace = true` is rewritten in the workspace root's `[workspace.dependencies]`, not in the member manifest."
    },
    {
      "id": "VER-CAS-08",
      "criterion": "The cascade aborts with E105 when it does not settle within 4 x (package count) + 1 steps, and with a grammar-mismatch error when a spec and the new version use different version grammars (SemVer vs PEP 440).",
      "is_error_case": true
    },
    {
      "id": "VER-GRP-01",
      "criterion": "All package members of a `[[fixed-group]]` receive the group's highest severity and one shared version, computed the same grammar- and pre-release-aware way as any other bump (VER-PRE-03): the alignment base is the on-disk version of the group's released member (a member with a release tag) if the group has one, otherwise the highest on-disk version among its members, bumped by that severity."
    },
    {
      "id": "VER-GRP-02",
      "criterion": "A fixed group whose released members have different on-disk versions aborts the run with E106, one whose released members use different version grammars (or whose untagged members do) aborts with E107, one whose released member has no on-disk base version aborts with E205, and one with no live member carrying a base version aborts with E206.",
      "is_error_case": true
    },
    {
      "id": "VER-GRP-06",
      "criterion": "A computed bump — for a single package or a fixed group's shared target — that would sort behind the version it was bumped from aborts the run with E207 instead of writing the regressed version to disk.",
      "is_error_case": true
    },
    {
      "id": "VER-GRP-03",
      "criterion": "When any member of a `[[linked-group]]` is bumped, every member receives the group's highest severity and all members move to the highest version any member's own bump produces (members at 1.4.0 and 2.7.3 with a minor bump both become 2.8.0)."
    },
    {
      "id": "VER-GRP-04",
      "criterion": "A package claimed by two groups is rejected: E109 when the claims use different spellings of the same package, and a group-conflict error when they use the same spelling.",
      "is_error_case": true
    },
    {
      "id": "VER-GRP-05",
      "criterion": "An attached platform package, or a fixed-group member naming a platform manifest, is not bumped as a package: when its owner is bumped, the platform manifest gets the owner's new version and the owner's `optionalDependencies` entry for it is pinned to that version. A co-located platform manifest that is also one of the owner's canonical manifests is written once, as part of the owner's own bump."
    },
    {
      "id": "VER-PRE-01",
      "criterion": "`callisto pre enter <tag>` writes `.changeset/pre.json` with `mode` `pre`, the tag, every package's current version under `initialVersions`, keyed by its display id (`foo`, or `cargo/foo` when another ecosystem has a `foo`) and an empty `changesets` list, then stages the file with git; under `--dry-run` it prints the content and writes nothing. For promoted packages, an older bare key is assigned to the unique historical owner at the commit that added pre.json; if no unique owner exists, version fails with E245."
    },
    {
      "id": "VER-PRE-02",
      "criterion": "`pre enter` fails when the tag is empty or whitespace, or when `.changeset/pre.json` exists with mode `pre` (also under `--dry-run`); when it exists with mode `exit`, `pre enter` instead resumes the cycle under the new tag, keeping its recorded `initialVersions` and `changesets`. `callisto pre exit` sets `mode` to `exit` and fails when the file is missing or already in `exit` mode.",
      "is_error_case": true
    },
    {
      "id": "VER-PRE-03",
      "criterion": "In pre mode, a bumped package's version is its `initialVersions` entry bumped by its severity plus `-{tag}.N`, where N starts at 0 and increments while the release part is unchanged (0.1.0 with a minor changeset and tag `beta` gives 0.2.0-beta.0, then 0.2.0-beta.1); PEP 440 packages use `aN` for tags `a`/`alpha`, `bN` for `b`/`beta`, `rcN` for `rc`/`c`/`pre`/`preview` (case-insensitive), and `.devN` for any other tag."
    },
    {
      "id": "VER-PRE-04",
      "criterion": "In pre mode, `version` never deletes a changeset from disk. A changeset whose id is not yet in `pre.json`'s `changesets` list counts toward severity, produces a changelog entry, and has its id added to `changesets`; a changeset whose id is already there still counts toward severity and the prerelease counter (VER-PRE-03) but produces no additional changelog entry. The `allow-empty-changesets`/`--strict` handling from VER-AGG-06 triggers only when no changeset -- new or already recorded -- resolves to a package this run, not merely when nothing new was added."
    },
    {
      "id": "VER-PRE-05",
      "criterion": "After `pre exit`, the next `version` moves every package at a prerelease version to its stable release (0.2.0-beta.1 becomes 0.2.0), consumes and deletes the pending changesets, and deletes `pre.json`."
    },
    {
      "id": "VER-PRE-06",
      "criterion": "A malformed `.changeset/pre.json` (invalid JSON, a missing `mode`, `tag`, `initialVersions` or `changesets` field, a mode other than `pre` or `exit`, or an unparsable version) makes `version` fail with E114 and write nothing; an unreadable file fails with E115.",
      "is_error_case": true
    },
    {
      "id": "VER-PRE-07",
      "criterion": "`callisto snapshot --tag <tag>` sets every workspace package, and every attached platform package and fixed-group platform manifest, to a snapshot version built from the same tag and sha7 (the first 7 characters of HEAD) in the package's own grammar: `0.0.0-{tag}-{sha7}` for a SemVer package, `0.0.0.dev0+{tag}.{sha7}` for a Pep440 package; it fails if HEAD cannot be resolved."
    },
    {
      "id": "VER-PRE-08",
      "criterion": "A snapshot writes manifests and refreshes each active ecosystem's existing lockfile, unconditionally (there is no `--no-refresh-lockfiles` for `snapshot`), so a subsequent locked install resolves against the snapshot version; it ignores and keeps pending changesets, writes no changelog or `pre.json`, and stages nothing in git; under `--dry-run` it writes nothing."
    },
    {
      "id": "VER-PRE-09",
      "criterion": "For every workspace dependency whose current spec does not cover the snapshot version, `snapshot` rewrites that spec using the source declaration's manifest ecosystem and declared key or spelling, including Cargo aliases. Inherited Cargo declarations are rewritten in the workspace root rather than the member manifest. A spec that already covers the snapshot version is left unchanged."
    },
    {
      "id": "VER-APPLY-01",
      "criterion": "`version` writes the new version to every canonical manifest of a bumped package, so both manifests of a dual-manifest package move together."
    },
    {
      "id": "VER-APPLY-02",
      "criterion": "Before writing a package or platform manifest, apply reads its current version: equal to the planned `from` it is written, equal to the target it is left unchanged, so applying the same plan again is safe."
    },
    {
      "id": "VER-APPLY-03",
      "criterion": "A manifest whose current version is neither the planned `from` nor the target aborts apply with E117 naming the path, the found version and both expected versions.",
      "is_error_case": true
    },
    {
      "id": "VER-APPLY-04",
      "criterion": "A manifest that receives a version bump and dependency rewrites in the same run is read once and written once with all changes, and a manifest already at its target with no rewrites is not rewritten. An owner's `optionalDependencies` pins, and edits to a workspace root `Cargo.toml` that is also a package manifest, are written separately."
    },
    {
      "id": "VER-APPLY-05",
      "criterion": "Files are written one at a time, each by atomic replacement, so an interrupted run never leaves a partially written file; a failing write stops the run and leaves earlier files in place."
    },
    {
      "id": "VER-APPLY-06",
      "criterion": "For each bumped package, apply prepends a `## {version}` section under the `# {package}` heading of its changelog (default `CHANGELOG.md` in the package directory, overridable with `changelog`), creating the file if missing and keeping CRLF line endings; a changelog that already has that heading is left unchanged."
    },
    {
      "id": "VER-APPLY-07",
      "criterion": "A changelog section lists each changeset summary as a bullet (continuation lines indented), an inferred bump as a commit subject with its short sha, a group bump as \"Released together with the `{group}` {fixed|linked} group.\", a new fixed-group member as \"Joined the `{group}` group at this version.\", a peer escalation as \"Peer dependency `{dep}` requires `{version}`\", and cascaded bumps as \"`{dep}` → `{version}`\" lines under a \"Dependency updates\" bullet."
    },
    {
      "id": "VER-APPLY-08",
      "criterion": "Outside pre mode, a successful `version` deletes the consumed changeset files, then stages every written manifest and changelog, `pre.json` changes, the existing lockfiles of affected ecosystems, and the changeset deletions (via `git rm --cached --ignore-unmatch`, which also succeeds for an already-deleted file)."
    },
    {
      "id": "VER-APPLY-09",
      "criterion": "`version --dry-run` prints the computed plan (text output starts with `[DRY-RUN]`) and writes, deletes and stages nothing."
    },
    {
      "id": "VER-APPLY-10",
      "criterion": "`version --emit-decision <path>` writes the release decision JSON to `<path>` relative to the workspace root after the plan has been applied successfully: `schemaVersion` 2, a digest, and one entry per canonical manifest of each bumped package (ecosystem-qualified name, target version, reasons) sorted by package. Reason `kind` is `changeset`, `inference`, `fixedGroup` or `linkedGroup` (with `groupId`), `cascade` (with source package and edge kind, `peer` for peer escalation) or `preReleasePolicy` (with the prerelease tag)."
    },
    {
      "id": "VER-APPLY-11",
      "criterion": "`--emit-decision` with `--dry-run` is rejected before any work, and a plan with no bumps, or whose group members have different target versions, fails to produce a decision before any file is written.",
      "is_error_case": true
    },
    {
      "id": "VER-APPLY-12",
      "criterion": "A diagnostic escalated to an error (for example `--strict` on the empty-changeset warning) is evaluated right after planning: `version` writes nothing -- not the manifests and changelog, not `pre.json`, not the `--emit-decision` file -- and exits with a failure status, instead of applying the plan and only then failing.",
      "is_error_case": true
    },
    {
      "id": "VER-APPLY-13",
      "criterion": "After planning but before any write, `version` refuses with E121 when a canonical manifest's on-disk version differs from its version at `HEAD` and either: the workspace's changesets directory still has a pending changeset as of `HEAD` (not yet consumed by a commit); or, outside an active pre-release cycle (`.changeset/pre.json` absent), a canonical manifest is staged in the git index but not yet committed. Both are the signature of a `version` run that wrote and staged its changes but never committed -- the second covers a changeset that was only ever a working-tree file (added and consumed by `version` without ever being committed), which the first check cannot see. A repository with no commits yet, a manifest/changesets directory that didn't exist at `HEAD`, or an active pre-release cycle (which legitimately reruns `version` without a commit in between) is never refused this way.",
      "is_error_case": true
    },
    {
      "id": "VER-APPLY-14",
      "criterion": "By default, applying a plan refreshes each active ecosystem's lockfile that exists on disk: `cargo update --workspace` for Cargo; for Pypi, `uv lock` if `uv.lock` exists, else `poetry lock --no-update` if `poetry.lock` exists, else `pdm lock --update-reuse` if `pdm.lock` exists; for Npm, `npm install --package-lock-only --ignore-scripts` for `package-lock.json`, `pnpm install --lockfile-only` for `pnpm-lock.yaml`, `yarn install --mode update-lockfile` for `yarn.lock`, and `bun install --lockfile-only` for `bun.lock` or `bun.lockb`, each independently when its lockfile is present. `--no-refresh-lockfiles` skips this; `--refresh-lockfiles` is accepted but has no effect."
    },
    {
      "id": "VER-APPLY-15",
      "criterion": "A lockfile refresh command that exits non-zero aborts `version` with E208 naming the lockfile and the exact command that failed, instead of recording the failure and continuing.",
      "is_error_case": true
    }
  ],
  "spec_file_path": "docs/specs/versioning.json"
}
{
  "id": "SPEC-WORKSPACE",
  "purpose": "Define how Callisto finds the workspace root, decides which manifests are packages, gives each package an identity, applies per-package config, and treats npm platform packages.",
  "scope": "Workspace root detection, project discovery and membership, package identity and dependency edges, [[package]]/[[package-set]] resolution, and npm platform packages.",
  "non_goals": [
    "Version planning, changelog and manifest write rules beyond platform version propagation.",
    "Release operation derivation and registry publishing of platform packages.",
    "Fixed and linked group semantics other than naming a platform package as a member.",
    "Ecosystems other than Cargo, npm and Python."
  ],
  "api_surface": [
    {
      "name": "Package key",
      "signature": "Package::key() -> Option<PackageKey>",
      "description": "A package's stable internal identity: the workspace-relative directory of its first canonical manifest. Promotion never changes it. Never printed as a package id.",
      "error_conditions": [
        "`None` only for a package with no canonical manifest, which workspace loading never produces."
      ]
    },
    {
      "name": "Package id",
      "signature": "PackageId = \"<name>\" | \"<ecosystem>/<name>\"",
      "description": "Display and selector form: the bare manifest name, or `<ecosystem>/<name>` once another ecosystem declares the same name. JSON output, messages, changeset entries and `pre.json` keys use it; `<ecosystem>/<name>` and `<ecosystem>:<name>` select the package whether or not it is promoted.",
      "error_conditions": [
        "A bare name shared by promoted packages is E103; a qualified name with no such manifest is E102."
      ]
    },
    {
      "name": "[[package]] match",
      "signature": "match = \"<name>\" | \"<ecosystem>:<name>\" | \"<ecosystem>/<name>\"",
      "description": "Exact package id. Ecosystem prefixes: cargo, npm, pypi.",
      "error_conditions": [
        "An empty, absolute, `..`-containing or otherwise unparseable id fails config loading."
      ]
    },
    {
      "name": "[[package-set]] match",
      "signature": "match = \"<glob>\" | \"<ecosystem>:<glob>\" | \"<ecosystem>/<glob>\"",
      "description": "Glob over package names. The colon and slash forms both scope the glob to an ecosystem; a bare glob matches any ecosystem.",
      "error_conditions": [
        "An invalid glob fails config loading."
      ]
    }
  ],
  "acceptance_criteria": [
    {
      "id": "WS-DISC-01",
      "criterion": "Root detection walks up from the start directory, never past the Git toplevel, and picks the nearest directory with a workspace marker (Cargo.toml with [workspace], package.json with `workspaces`, pnpm-workspace.yaml, or a .moon directory); with no marker it picks the outermost directory with a package manifest (Cargo.toml with [package], package.json, or pyproject.toml)."
    },
    {
      "id": "WS-DISC-02",
      "criterion": "Root detection fails with E030 naming the start directory and Git toplevel when no marker or package manifest exists up to the toplevel, and with E058 (help suggests `git init`) when the start directory is not inside a Git repository.",
      "is_error_case": true
    },
    {
      "id": "WS-DISC-03",
      "criterion": "Discovery treats every directory under the root whose Cargo.toml, package.json or pyproject.toml parses and declares a package name as a candidate, following symlinks up to 32 levels deep and skipping hidden and gitignored paths and directories named target, node_modules, .git, .moon and dist; a manifest without a name is not a package. A manifest that fails to parse is a coded error naming its path and the parse error when the path is admitted by explicit workspace membership or shares a directory with an admitted manifest, otherwise it is a warning naming the path and the parse error, and discovery continues without it."
    },
    {
      "id": "WS-DISC-04",
      "criterion": "A Cargo candidate is admitted when the root Cargo.toml [workspace] has no `members` key or its path matches `members`, and its path does not match `exclude`; Python candidates follow the same rules using pyproject.toml [tool.uv.workspace]."
    },
    {
      "id": "WS-DISC-05",
      "criterion": "Membership globs match root-relative paths where `*` matches one path segment, `**` matches any depth, and an entry starting with `!` removes matching paths from the list's other entries."
    },
    {
      "id": "WS-DISC-06",
      "criterion": "With no root manifest or no workspace table for an ecosystem, every candidate of that ecosystem is admitted; an empty `members`, `workspaces` or `packages` list admits none except a hybrid root."
    },
    {
      "id": "WS-DISC-07",
      "criterion": "An npm candidate is admitted when its path matches the `packages` list of the root pnpm-workspace.yaml, or, when that file is absent or unusable, the root package.json `workspaces` array; with neither, all npm candidates are admitted."
    },
    {
      "id": "WS-DISC-08",
      "criterion": "A hybrid root (root Cargo.toml with both [package] and [workspace], root pyproject.toml with both [project] and [tool.uv.workspace], or a root package.json with a `name`) is always admitted, even when `exclude` matches `.` or the member globs do not. A root package.json that is both `private` and versionless is never discovered as an npm package (it only holds `workspaces`), regardless of admission."
    },
    {
      "id": "WS-DISC-09",
      "criterion": "Malformed membership input never fails discovery: an unparseable root manifest or a `members`, `workspaces` or `packages` value that is not an array of strings is treated as absent, an unparseable, empty or `packages`-less pnpm-workspace.yaml falls back to package.json `workspaces`, and a malformed `exclude` excludes nothing.",
      "is_error_case": true
    },
    {
      "id": "WS-DISC-10",
      "criterion": "An invalid glob in `members`, `exclude`, `workspaces` or `packages` is ignored while the list's valid entries still apply.",
      "is_error_case": true
    },
    {
      "id": "WS-ID-01",
      "criterion": "A package whose name is claimed by no other directory gets a bare id equal to its manifest name (for example `foo` or `@scope/foo`)."
    },
    {
      "id": "WS-ID-02",
      "criterion": "A dual-manifest package (one directory with several admitted manifests) is one package whose id comes from Cargo.toml, else package.json, else pyproject.toml, and each manifest's own name still resolves to that package within its ecosystem -- including through `--package`, `add` and a changeset entry naming the package by a non-primary manifest's own name, not only its primary name."
    },
    {
      "id": "WS-ID-03",
      "criterion": "When two or more directories declare the same name and no ecosystem declares it in more than one of them, each package is promoted to an ecosystem-qualified id, displayed as `cargo/foo`. Promotion preserves the package's key (its workspace-relative directory) and CHANGELOG path; `cargo/foo` selects it in both states. Newly created default tags use `{display id}@{version}`, so promotion changes their namespace. A promoted package's last tag is also found among `foo@*` tags whose commit contains its manifest and no other same-named package's. A bare `pre.json` `initialVersions` key moves to the one same-named package that existed when `pre.json` was added, else `version` fails with E245."
    },
    {
      "id": "WS-ID-04",
      "criterion": "When two directories declare the same name in the same ecosystem (including a dual-manifest Cargo+npm `foo` and an npm-only `foo`), loading fails with E100 naming both paths.",
      "is_error_case": true
    },
    {
      "id": "WS-ID-05",
      "criterion": "A `[[fixed-group]]` or `[[linked-group]]` member written `cargo:foo` or `cargo/foo` resolves to package `foo` when a Cargo manifest declares `foo`, promoted or not, through the same selector resolver used for `--package` and changesets; a member naming an ecosystem with no such manifest fails loading with E108, and a bare member name ambiguous across ecosystems fails loading with E103 (not E108).",
      "is_error_case": true
    },
    {
      "id": "WS-ID-06",
      "criterion": "A changeset, `callisto add --package` or `callisto matrix --package` naming the bare name of promoted packages fails with E103 listing every qualified candidate and showing the qualified form to write; naming a package that does not exist under that name in that ecosystem fails with E102.",
      "is_error_case": true
    },
    {
      "id": "WS-ID-07",
      "criterion": "A dependency edge is created only to a workspace package that declares the dependency's name in the depending manifest's own ecosystem; a name declared only in other ecosystems creates no edge and one `unknown-package` warning listing the candidates (`cargo:foo`), and a name no workspace package declares creates no edge and no diagnostic."
    },
    {
      "id": "WS-ID-08",
      "criterion": "A package whose explicit `tag-template` equals another package's default tag template makes `status` and `version` fail with E101 naming both packages and the template.",
      "is_error_case": true
    },
    {
      "id": "WS-ID-09",
      "criterion": "A discovered package whose canonical manifests use different version grammars fails with E007 before version planning or init writes. This includes co-located Cargo.toml and pyproject.toml, whether the Python version is static or declared dynamic; matching numeric version strings do not bypass the grammar check.",
      "is_error_case": true
    },
    {
      "id": "WS-CFG-01",
      "criterion": "For each package, the first ecosystem-prefixed `[[package]]` rule whose ecosystem the package actually has a manifest in and whose name matches applies, regardless of declaration order relative to bare rules; a prefixed rule for an ecosystem the package has no manifest in never applies, even to a same-named package in another ecosystem. If no prefixed rule applies, the first matching bare rule applies."
    },
    {
      "id": "WS-CFG-03",
      "criterion": "A bare `[[package]]` rule that would apply to a promoted package fails loading with E103 listing the qualified candidates; prefixed rules for the same packages load normally.",
      "is_error_case": true
    },
    {
      "id": "WS-CFG-04",
      "criterion": "A `[[package-set]]` rule applies only when no `[[package]]` rule matches, the first matching set in declaration order wins, and a `cargo:`/`cargo/`, `npm:`/`npm/` or `pypi:`/`pypi/` prefix restricts it to packages with a manifest in that ecosystem."
    },
    {
      "id": "WS-CFG-05",
      "criterion": "A matched rule overrides only the fields it sets; otherwise a package uses release trigger `changeset`, `CHANGELOG.md` in its directory (a configured changelog is relative to the package directory), and the publish targets its manifests declare."
    },
    {
      "id": "WS-CFG-06",
      "criterion": "A `publish-to` override whose target ecosystem is not among the matched package's manifest ecosystems fails loading with E119.",
      "is_error_case": true
    },
    {
      "id": "WS-CFG-07",
      "criterion": "A `[[package-set]]` that matches no package emits one `package-set-matched-nothing` warning naming its pattern; a set matching a package that a `[[package]]` rule shadows counts as matched.",
      "is_error_case": true
    },
    {
      "id": "WS-CFG-08",
      "criterion": "A bare `[[package]]` rule matching packages whose manifests span two or more ecosystems, such as a dual-manifest package, emits one non-fatal `bare-rule-matches-multiple-ecosystems` warning; prefixed rules and `[[package-set]]` rules never emit it.",
      "is_error_case": true
    },
    {
      "id": "WS-CFG-09",
      "criterion": "A `[[package]]` rule that matches no package emits one `package-rule-matched-nothing` warning naming the rule.",
      "is_error_case": true
    },
    {
      "id": "WS-PLAT-01",
      "criterion": "A package.json with non-empty `os` and `cpu` arrays is an npm platform package whose platform and arch are the first entries; for Linux its ABI is `gnueabihf`, `gnu` or `musl` from the name's `-<abi>` suffix, otherwise none."
    },
    {
      "id": "WS-PLAT-02",
      "criterion": "An npm-only platform package named in the `optionalDependencies` of exactly one admitted npm package becomes an attached platform package of that owner, inside or outside the npm workspace globs: it is not its own package and adds no publish targets to the owner."
    },
    {
      "id": "WS-PLAT-03",
      "criterion": "A co-located platform manifest belongs to its directory's package, is never attached to another owner, and a `[[fixed-group]]` member may name any platform manifest by its own npm name."
    },
    {
      "id": "WS-PLAT-04",
      "criterion": "When an owner is versioned or snapshotted, each attached platform manifest receives the owner's new version and the owner's `optionalDependencies` pins update to it, with no fixed group required."
    },
    {
      "id": "WS-PLAT-05",
      "criterion": "An admitted platform package named in no owner's or several owners' `optionalDependencies` stays its own package and emits a `platform-package-without-owner` warning with its manifest path and the owner count or paths.",
      "is_error_case": true
    },
    {
      "id": "WS-PLAT-06",
      "criterion": "A platform package outside the npm workspace named by several owners emits `platform-package-without-owner` stating it is not released; one named by no owner stays undiscovered with no diagnostic.",
      "is_error_case": true
    }
  ],
  "spec_file_path": "docs/specs/workspace.json"
}

item.aggregated_output:
{
  "id": "SPEC-VERSIONING",
  "purpose": "Define how `callisto version`, `pre` and `snapshot` turn pending changesets and commits into new package versions, dependency rewrites, changelog sections and an optional release decision file.",
  "scope": "Changeset file format, severity aggregation and commit inference, dependency cascade, fixed and linked groups, prerelease and snapshot versions, and applying the plan to disk.",
  "non_goals": [
    "Creating changesets interactively with `callisto add`.",
    "Publishing, tagging, and verifying a committed release decision during `release`.",
    "Package discovery, workspace config parsing and dependency graph construction.",
    "Release PR body composition."
  ],
  "api_surface": [
    {
      "name": "callisto version",
      "signature": "callisto version [--strict] [--allow-empty-changesets] [--no-refresh-lockfiles] [--emit-decision <PATH>] [--dry-run]",
      "description": "Computes the version plan from pending changesets, inference, cascade and groups, then applies it to disk and stages it in git."
    },
    {
      "name": "callisto pre",
      "signature": "callisto pre enter <TAG> | callisto pre exit",
      "description": "Enters or exits prerelease mode by writing `.changeset/pre.json`."
    },
    {
      "name": "callisto snapshot",
      "signature": "callisto snapshot --tag <TAG> [--strict] [--dry-run]",
      "description": "Sets every package to a throwaway native-grammar snapshot version without consuming changesets: `0.0.0-{tag}-{sha7}` for SemVer and `0.0.0.dev0+{tag}.{sha7}` for PEP 440."
    }
  ],
  "acceptance_criteria": [
    {
      "id": "VER-CS-01",
      "criterion": "A changeset is a Markdown file whose line 1 is `---`, followed by one `name: severity` entry per line, a closing `---` line and a free-text summary; blank lines and lines starting with `#` inside the frontmatter are ignored. Severities are `major`, `minor`, `patch` and `none` (ordered none < patch < minor < major), read case-insensitively and written lowercase."
    },
    {
      "id": "VER-CS-02",
      "criterion": "A package name may be double-quoted, and a quoted name may contain `:` (`\"maven/org.example:foo-core\": major` parses as that name with severity major); an unquoted name is split at its last `:`."
    },
    {
      "id": "VER-CS-03",
      "criterion": "A leading UTF-8 BOM is ignored, CRLF and CR line endings parse the same as LF, the summary is trimmed of surrounding whitespace, and a changeset with a summary but no entries is valid."
    },
    {
      "id": "VER-CS-04",
      "criterion": "Parsing fails with E040 when line 1 is not `---`, E041 when the frontmatter is never closed, and E055 when there are entries but the summary is empty or whitespace-only. A changeset with no entries and no summary (the shape `@changesets/cli add --empty` writes) parses as a valid, empty changeset.",
      "is_error_case": true
    },
    {
      "id": "VER-CS-05",
      "criterion": "Parsing fails on a bad entry line and reports its line number: unclosed quoted name (E042), text between a quoted name and its `:` (E043), no `:` (E044), empty name (E045), unknown severity (E046), or a name already used in the same file (E047, also citing the first line).",
      "is_error_case": true
    },
    {
      "id": "VER-CS-06",
      "criterion": "Writing a changeset emits `---`, one `name: severity` line per entry in order, `---`, a blank line, the trimmed summary and a trailing newline; a name is quoted when it starts with a YAML-significant character (such as `@`, `-`, `#`, `\"` or a space), contains `:` or `#`, or ends with a space."
    },
    {
      "id": "VER-CS-07",
      "criterion": "Writing fails for an empty summary (E049 with no entries, E056 with entries), an empty package name (E057), or a name containing `\"`.",
      "is_error_case": true
    },
    {
      "id": "VER-CS-08",
      "criterion": "`version` reads every `.md` file directly inside the configured changesets directory (default `.changeset`) except `README.md`, in path order; a missing directory means no changesets, and one unparsable file aborts the run with an error naming that file.",
      "is_error_case": true
    },
    {
      "id": "VER-AGG-01",
      "criterion": "A package's severity is the highest severity among all changeset entries naming it and its inferred severity."
    },
    {
      "id": "VER-AGG-02",
      "criterion": "An entry name resolves to a workspace package by prefixed id (`cargo/foo`) or bare name; a bare name that matches packages in two or more ecosystems aborts the run with an ambiguous-name error (E103).",
      "is_error_case": true
    },
    {
      "id": "VER-AGG-03",
      "criterion": "An entry naming a package not in the workspace, or an invalid name, produces an unknown-package warning, and a changeset with any such unresolved entry stays on disk unconsumed, even when its other entries resolve. An entry with severity `none` causes no bump and no changelog line, but its changeset is still consumed."
    },
    {
      "id": "VER-AGG-04",
      "criterion": "Commit inference runs only for packages with `release-trigger = \"auto\"`; packages with the default `release-trigger = \"changeset\"` take severity from changesets alone. Inference reads conventional commits touching the package's directory since its last release tag (all history when untagged): a `!` marker or `BREAKING CHANGE`/`BREAKING-CHANGE` footer maps to major, `feat` to minor, `fix`/`perf`/`revert` to patch, anything else to none."
    },
    {
      "id": "VER-AGG-05",
      "criterion": "`pre-major-inference` changes only inferred severity, and only for a package with a prior release tag whose current version is `0.y.z` with y >= 1: `conservative` maps major to minor, `conservative-feat` also maps minor to patch, and `off` (default) changes nothing."
    },
    {
      "id": "VER-AGG-06",
      "criterion": "When no changeset is consumed, `version` warns \"No pending changesets found in workspace\" unless `--allow-empty-changesets` or `[validation] allow-empty-changesets = true` is set; with `--strict` the warning is an error and `version` exits with a failure status.",
      "is_error_case": true
    },
    {
      "id": "VER-CAS-01",
      "criterion": "When a package is bumped, each dependent's spec on it is tested against the new version. Under `[cascade] mode = \"out-of-range\"` (default) a runtime, optional, build or peer dependent is bumped only when its spec no longer covers the new version; under `mode = \"always\"` it is bumped regardless. Coverage governs only the dependent's own severity bump; whether its spec is rewritten follows VER-CAS-06."
    },
    {
      "id": "VER-CAS-02",
      "criterion": "A cascaded bump has severity `bump-severity` (`patch` default, or `minor`), never lowers a severity the dependent already has, and propagates to that dependent's own dependents."
    },
    {
      "id": "VER-CAS-03",
      "criterion": "With `peer-escalation = true` (default), a peer dependent whose spec no longer covers a minor or major bump of its dependency receives a major bump; a patch bump of the dependency cascades at `bump-severity`."
    },
    {
      "id": "VER-CAS-04",
      "criterion": "A dev dependent is never bumped by the cascade, but its spec is still rewritten when it no longer covers the new version."
    },
    {
      "id": "VER-CAS-05",
      "criterion": "Coverage: an exact spec covers only the equal version, a bare Cargo version is a caret requirement, a caret requirement never covers a prerelease, a Cargo `workspace = true` spec is tested using the root `[workspace.dependencies]` spec, and an npm `workspace:` spec always covers. A catalog or other untestable spec is treated as covering and never rewritten; a catalog spec emits a CatalogSpecNotRewritten warning."
    },
    {
      "id": "VER-CAS-06",
      "criterion": "A spec that no longer covers the new version is rewritten to it, keeping the operator and precision for Cargo and npm (`^1.2` becomes `^2.0` for 2.0.0), or to the exact version for npm when `preserve-npm-ranges = false`. A runtime, optional, build or peer dependent that is itself released in this run, for any reason, has every such spec on a bumped internal dependency raised to the dependency's new version the same way, even when the spec still covers it; a dependent that is not releasing keeps its spec unless out of range. `workspace = true`, npm `workspace:` and catalog specs are never rewritten by either rule, and a dev dependent's spec is rewritten only when out of range. A spec that cannot be rewritten mechanically, such as an npm range with spaces, `||`, a hyphen or a wildcard, is left unchanged with a RangeNotRoundTrippable warning."
    },
    {
      "id": "VER-CAS-07",
      "criterion": "A rewrite uses the source declaration's manifest ecosystem and preserves its declared dependency key or spelling, independent of either package's display prefix. A Cargo dependency's `package` name resolves its native target while edits retain its alias; inherited aliases resolve the workspace root's declaration. Python distribution names match using PEP 503 normalization while edits retain the spelling in the dependency declaration. A Cargo dependency inherited with `workspace = true` is rewritten in the workspace root's `[workspace.dependencies]`, not in the member manifest."
    },
    {
      "id": "VER-CAS-08",
      "criterion": "The cascade aborts with E105 when it does not settle within 4 x (package count) + 1 steps, and with a grammar-mismatch error when a spec and the new version use different version grammars (SemVer vs PEP 440).",
      "is_error_case": true
    },
    {
      "id": "VER-GRP-01",
      "criterion": "All package members of a `[[fixed-group]]` receive the group's highest severity and one shared version, computed the same grammar- and pre-release-aware way as any other bump (VER-PRE-03): the alignment base is the on-disk version of the group's released member (a member with a release tag) if the group has one, otherwise the highest on-disk version among its members, bumped by that severity."
    },
    {
      "id": "VER-GRP-02",
      "criterion": "A fixed group whose released members have different on-disk versions aborts the run with E106, one whose released members use different version grammars (or whose untagged members do) aborts with E107, one whose released member has no on-disk base version aborts with E205, and one with no live member carrying a base version aborts with E206.",
      "is_error_case": true
    },
    {
      "id": "VER-GRP-06",
      "criterion": "A computed bump — for a single package or a fixed group's shared target — that would sort behind the version it was bumped from aborts the run with E207 instead of writing the regressed version to disk.",
      "is_error_case": true
    },
    {
      "id": "VER-GRP-03",
      "criterion": "When any member of a `[[linked-group]]` is bumped, every member receives the group's highest severity and all members move to the highest version any member's own bump produces (members at 1.4.0 and 2.7.3 with a minor bump both become 2.8.0)."
    },
    {
      "id": "VER-GRP-04",
      "criterion": "A package claimed by two groups is rejected: E109 when the claims use different spellings of the same package, and a group-conflict error when they use the same spelling.",
      "is_error_case": true
    },
    {
      "id": "VER-GRP-05",
      "criterion": "An attached platform package, or a fixed-group member naming a platform manifest, is not bumped as a package: when its owner is bumped, the platform manifest gets the owner's new version and the owner's `optionalDependencies` entry for it is pinned to that version. A co-located platform manifest that is also one of the owner's canonical manifests is written once, as part of the owner's own bump."
    },
    {
      "id": "VER-PRE-01",
      "criterion": "`callisto pre enter <tag>` writes `.changeset/pre.json` with `mode` `pre`, the tag, every package's current version under `initialVersions`, keyed by its display id (`foo`, or `cargo/foo` when another ecosystem has a `foo`) and an empty `changesets` list, then stages the file with git; under `--dry-run` it prints the content and writes nothing. For promoted packages, an older bare key is assigned to the unique historical owner at the commit that added pre.json; if no unique owner exists, version fails with E245."
    },
    {
      "id": "VER-PRE-02",
      "criterion": "`pre enter` fails when the tag is empty or whitespace, or when `.changeset/pre.json` exists with mode `pre` (also under `--dry-run`); when it exists with mode `exit`, `pre enter` instead resumes the cycle under the new tag, keeping its recorded `initialVersions` and `changesets`. `callisto pre exit` sets `mode` to `exit` and fails when the file is missing or already in `exit` mode.",
      "is_error_case": true
    },
    {
      "id": "VER-PRE-03",
      "criterion": "In pre mode, a bumped package's version is its `initialVersions` entry bumped by its severity plus `-{tag}.N`, where N starts at 0 and increments while the release part is unchanged (0.1.0 with a minor changeset and tag `beta` gives 0.2.0-beta.0, then 0.2.0-beta.1); PEP 440 packages use `aN` for tags `a`/`alpha`, `bN` for `b`/`beta`, `rcN` for `rc`/`c`/`pre`/`preview` (case-insensitive), and `.devN` for any other tag."
    },
    {
      "id": "VER-PRE-04",
      "criterion": "In pre mode, `version` never deletes a changeset from disk. A changeset whose id is not yet in `pre.json`'s `changesets` list counts toward severity, produces a changelog entry, and has its id added to `changesets`; a changeset whose id is already there still counts toward severity and the prerelease counter (VER-PRE-03) but produces no additional changelog entry. The `allow-empty-changesets`/`--strict` handling from VER-AGG-06 triggers only when no changeset -- new or already recorded -- resolves to a package this run, not merely when nothing new was added."
    },
    {
      "id": "VER-PRE-05",
      "criterion": "After `pre exit`, the next `version` moves every package at a prerelease version to its stable release (0.2.0-beta.1 becomes 0.2.0), consumes and deletes the pending changesets, and deletes `pre.json`."
    },
    {
      "id": "VER-PRE-06",
      "criterion": "A malformed `.changeset/pre.json` (invalid JSON, a missing `mode`, `tag`, `initialVersions` or `changesets` field, a mode other than `pre` or `exit`, or an unparsable version) makes `version` fail with E114 and write nothing; an unreadable file fails with E115.",
      "is_error_case": true
    },
    {
      "id": "VER-PRE-07",
      "criterion": "`callisto snapshot --tag <tag>` sets every workspace package, and every attached platform package and fixed-group platform manifest, to a snapshot version built from the same tag and sha7 (the first 7 characters of HEAD) in the package's own grammar: `0.0.0-{tag}-{sha7}` for a SemVer package, `0.0.0.dev0+{tag}.{sha7}` for a Pep440 package; it fails if HEAD cannot be resolved."
    },
    {
      "id": "VER-PRE-08",
      "criterion": "A snapshot writes manifests and refreshes each active ecosystem's existing lockfile, unconditionally (there is no `--no-refresh-lockfiles` for `snapshot`), so a subsequent locked install resolves against the snapshot version; it ignores and keeps pending changesets, writes no changelog or `pre.json`, and stages nothing in git; under `--dry-run` it writes nothing."
    },
    {
      "id": "VER-PRE-09",
      "criterion": "For every workspace dependency whose current spec does not cover the snapshot version, `snapshot` rewrites that spec using the source declaration's manifest ecosystem and declared key or spelling, including Cargo aliases. Inherited Cargo declarations are rewritten in the workspace root rather than the member manifest. A spec that already covers the snapshot version is left unchanged."
    },
    {
      "id": "VER-APPLY-01",
      "criterion": "`version` writes the new version to every canonical manifest of a bumped package, so both manifests of a dual-manifest package move together."
    },
    {
      "id": "VER-APPLY-02",
      "criterion": "Before writing a package or platform manifest, apply reads its current version: equal to the planned `from` it is written, equal to the target it is left unchanged, so applying the same plan again is safe."
    },
    {
      "id": "VER-APPLY-03",
      "criterion": "A manifest whose current version is neither the planned `from` nor the target aborts apply with E117 naming the path, the found version and both expected versions.",
      "is_error_case": true
    },
    {
      "id": "VER-APPLY-04",
      "criterion": "A manifest that receives a version bump and dependency rewrites in the same run is read once and written once with all changes, and a manifest already at its target with no rewrites is not rewritten. An owner's `optionalDependencies` pins, and edits to a workspace root `Cargo.toml` that is also a package manifest, are written separately."
    },
    {
      "id": "VER-APPLY-05",
      "criterion": "Files are written one at a time, each by atomic replacement, so an interrupted run never leaves a partially written file; a failing write stops the run and leaves earlier files in place."
    },
    {
      "id": "VER-APPLY-06",
      "criterion": "For each bumped package, apply prepends a `## {version}` section under the `# {package}` heading of its changelog (default `CHANGELOG.md` in the package directory, overridable with `changelog`), creating the file if missing and keeping CRLF line endings; a changelog that already has that heading is left unchanged."
    },
    {
      "id": "VER-APPLY-07",
      "criterion": "A changelog section lists each changeset summary as a bullet (continuation lines indented), an inferred bump as a commit subject with its short sha, a group bump as \"Released together with the `{group}` {fixed|linked} group.\", a new fixed-group member as \"Joined the `{group}` group at this version.\", a peer escalation as \"Peer dependency `{dep}` requires `{version}`\", and cascaded bumps as \"`{dep}` → `{version}`\" lines under a \"Dependency updates\" bullet."
    },
    {
      "id": "VER-APPLY-08",
      "criterion": "Outside pre mode, a successful `version` deletes the consumed changeset files, then stages every written manifest and changelog, `pre.json` changes, the existing lockfiles of affected ecosystems, and the changeset deletions (via `git rm --cached --ignore-unmatch`, which also succeeds for an already-deleted file)."
    },
    {
      "id": "VER-APPLY-09",
      "criterion": "`version --dry-run` prints the computed plan (text output starts with `[DRY-RUN]`) and writes, deletes and stages nothing."
    },
    {
      "id": "VER-APPLY-10",
      "criterion": "`version --emit-decision <path>` writes the release decision JSON to `<path>` relative to the workspace root after the plan has been applied successfully: `schemaVersion` 2, a digest, and one entry per canonical manifest of each bumped package (ecosystem-qualified name, target version, reasons) sorted by package. Reason `kind` is `changeset`, `inference`, `fixedGroup` or `linkedGroup` (with `groupId`), `cascade` (with source package and edge kind, `peer` for peer escalation) or `preReleasePolicy` (with the prerelease tag)."
    },
    {
      "id": "VER-APPLY-11",
      "criterion": "`--emit-decision` with `--dry-run` is rejected before any work, and a plan with no bumps, or whose group members have different target versions, fails to produce a decision before any file is written.",
      "is_error_case": true
    },
    {
      "id": "VER-APPLY-12",
      "criterion": "A diagnostic escalated to an error (for example `--strict` on the empty-changeset warning) is evaluated right after planning: `version` writes nothing -- not the manifests and changelog, not `pre.json`, not the `--emit-decision` file -- and exits with a failure status, instead of applying the plan and only then failing.",
      "is_error_case": true
    },
    {
      "id": "VER-APPLY-13",
      "criterion": "After planning but before any write, `version` refuses with E121 when a canonical manifest's on-disk version differs from its version at `HEAD` and either: the workspace's changesets directory still has a pending changeset as of `HEAD` (not yet consumed by a commit); or, outside an active pre-release cycle (`.changeset/pre.json` absent), a canonical manifest is staged in the git index but not yet committed. Both are the signature of a `version` run that wrote and staged its changes but never committed -- the second covers a changeset that was only ever a working-tree file (added and consumed by `version` without ever being committed), which the first check cannot see. A repository with no commits yet, a manifest/changesets directory that didn't exist at `HEAD`, or an active pre-release cycle (which legitimately reruns `version` without a commit in between) is never refused this way.",
      "is_error_case": true
    },
    {
      "id": "VER-APPLY-14",
      "criterion": "By default, applying a plan refreshes each active ecosystem's lockfile that exists on disk: `cargo update --workspace` for Cargo; for Pypi, `uv lock` if `uv.lock` exists, else `poetry lock --no-update` if `poetry.lock` exists, else `pdm lock --update-reuse` if `pdm.lock` exists; for Npm, `npm install --package-lock-only --ignore-scripts` for `package-lock.json`, `pnpm install --lockfile-only` for `pnpm-lock.yaml`, `yarn install --mode update-lockfile` for `yarn.lock`, and `bun install --lockfile-only` for `bun.lock` or `bun.lockb`, each independently when its lockfile is present. `--no-refresh-lockfiles` skips this; `--refresh-lockfiles` is accepted but has no effect."
    },
    {
      "id": "VER-APPLY-15",
      "criterion": "A lockfile refresh command that exits non-zero aborts `version` with E208 naming the lockfile and the exact command that failed, instead of recording the failure and continuing.",
      "is_error_case": true
    }
  ],
  "spec_file_path": "docs/specs/versioning.json"
}
{
  "id": "SPEC-WORKSPACE",
  "purpose": "Define how Callisto finds the workspace root, decides which manifests are packages, gives each package an identity, applies per-package config, and treats npm platform packages.",
  "scope": "Workspace root detection, project discovery and membership, package identity and dependency edges, [[package]]/[[package-set]] resolution, and npm platform packages.",
  "non_goals": [
    "Version planning, changelog and manifest write rules beyond platform version propagation.",
    "Release operation derivation and registry publishing of platform packages.",
    "Fixed and linked group semantics other than naming a platform package as a member.",
    "Ecosystems other than Cargo, npm and Python."
  ],
  "api_surface": [
    {
      "name": "Package key",
      "signature": "Package::key() -> Option<PackageKey>",
      "description": "A package's stable internal identity: the workspace-relative directory of its first canonical manifest. Promotion never changes it. Never printed as a package id.",
      "error_conditions": [
        "`None` only for a package with no canonical manifest, which workspace loading never produces."
      ]
    },
    {
      "name": "Package id",
      "signature": "PackageId = \"<name>\" | \"<ecosystem>/<name>\"",
      "description": "Display and selector form: the bare manifest name, or `<ecosystem>/<name>` once another ecosystem declares the same name. JSON output, messages, changeset entries and `pre.json` keys use it; `<ecosystem>/<name>` and `<ecosystem>:<name>` select the package whether or not it is promoted.",
      "error_conditions": [
        "A bare name shared by promoted packages is E103; a qualified name with no such manifest is E102."
      ]
    },
    {
      "name": "[[package]] match",
      "signature": "match = \"<name>\" | \"<ecosystem>:<name>\" | \"<ecosystem>/<name>\"",
      "description": "Exact package id. Ecosystem prefixes: cargo, npm, pypi.",
      "error_conditions": [
        "An empty, absolute, `..`-containing or otherwise unparseable id fails config loading."
      ]
    },
    {
      "name": "[[package-set]] match",
      "signature": "match = \"<glob>\" | \"<ecosystem>:<glob>\" | \"<ecosystem>/<glob>\"",
      "description": "Glob over package names. The colon and slash forms both scope the glob to an ecosystem; a bare glob matches any ecosystem.",
      "error_conditions": [
        "An invalid glob fails config loading."
      ]
    }
  ],
  "acceptance_criteria": [
    {
      "id": "WS-DISC-01",
      "criterion": "Root detection walks up from the start directory, never past the Git toplevel, and picks the nearest directory with a workspace marker (Cargo.toml with [workspace], package.json with `workspaces`, pnpm-workspace.yaml, or a .moon directory); with no marker it picks the outermost directory with a package manifest (Cargo.toml with [package], package.json, or pyproject.toml)."
    },
    {
      "id": "WS-DISC-02",
      "criterion": "Root detection fails with E030 naming the start directory and Git toplevel when no marker or package manifest exists up to the toplevel, and with E058 (help suggests `git init`) when the start directory is not inside a Git repository.",
      "is_error_case": true
    },
    {
      "id": "WS-DISC-03",
      "criterion": "Discovery treats every directory under the root whose Cargo.toml, package.json or pyproject.toml parses and declares a package name as a candidate, following symlinks up to 32 levels deep and skipping hidden and gitignored paths and directories named target, node_modules, .git, .moon and dist; a manifest without a name is not a package. A manifest that fails to parse is a coded error naming its path and the parse error when the path is admitted by explicit workspace membership or shares a directory with an admitted manifest, otherwise it is a warning naming the path and the parse error, and discovery continues without it."
    },
    {
      "id": "WS-DISC-04",
      "criterion": "A Cargo candidate is admitted when the root Cargo.toml [workspace] has no `members` key or its path matches `members`, and its path does not match `exclude`; Python candidates follow the same rules using pyproject.toml [tool.uv.workspace]."
    },
    {
      "id": "WS-DISC-05",
      "criterion": "Membership globs match root-relative paths where `*` matches one path segment, `**` matches any depth, and an entry starting with `!` removes matching paths from the list's other entries."
    },
    {
      "id": "WS-DISC-06",
      "criterion": "With no root manifest or no workspace table for an ecosystem, every candidate of that ecosystem is admitted; an empty `members`, `workspaces` or `packages` list admits none except a hybrid root."
    },
    {
      "id": "WS-DISC-07",
      "criterion": "An npm candidate is admitted when its path matches the `packages` list of the root pnpm-workspace.yaml, or, when that file is absent or unusable, the root package.json `workspaces` array; with neither, all npm candidates are admitted."
    },
    {
      "id": "WS-DISC-08",
      "criterion": "A hybrid root (root Cargo.toml with both [package] and [workspace], root pyproject.toml with both [project] and [tool.uv.workspace], or a root package.json with a `name`) is always admitted, even when `exclude` matches `.` or the member globs do not. A root package.json that is both `private` and versionless is never discovered as an npm package (it only holds `workspaces`), regardless of admission."
    },
    {
      "id": "WS-DISC-09",
      "criterion": "Malformed membership input never fails discovery: an unparseable root manifest or a `members`, `workspaces` or `packages` value that is not an array of strings is treated as absent, an unparseable, empty or `packages`-less pnpm-workspace.yaml falls back to package.json `workspaces`, and a malformed `exclude` excludes nothing.",
      "is_error_case": true
    },
    {
      "id": "WS-DISC-10",
      "criterion": "An invalid glob in `members`, `exclude`, `workspaces` or `packages` is ignored while the list's valid entries still apply.",
      "is_error_case": true
    },
    {
      "id": "WS-ID-01",
      "criterion": "A package whose name is claimed by no other directory gets a bare id equal to its manifest name (for example `foo` or `@scope/foo`)."
    },
    {
      "id": "WS-ID-02",
      "criterion": "A dual-manifest package (one directory with several admitted manifests) is one package whose id comes from Cargo.toml, else package.json, else pyproject.toml, and each manifest's own name still resolves to that package within its ecosystem -- including through `--package`, `add` and a changeset entry naming the package by a non-primary manifest's own name, not only its primary name."
    },
    {
      "id": "WS-ID-03",
      "criterion": "When two or more directories declare the same name and no ecosystem declares it in more than one of them, each package is promoted to an ecosystem-qualified id, displayed as `cargo/foo`. Promotion preserves the package's key (its workspace-relative directory) and CHANGELOG path; `cargo/foo` selects it in both states. Newly created default tags use `{display id}@{version}`, so promotion changes their namespace. A promoted package's last tag is also found among `foo@*` tags whose commit contains its manifest and no other same-named package's. A bare `pre.json` `initialVersions` key moves to the one same-named package that existed when `pre.json` was added, else `version` fails with E245."
    },
    {
      "id": "WS-ID-04",
      "criterion": "When two directories declare the same name in the same ecosystem (including a dual-manifest Cargo+npm `foo` and an npm-only `foo`), loading fails with E100 naming both paths.",
      "is_error_case": true
    },
    {
      "id": "WS-ID-05",
      "criterion": "A `[[fixed-group]]` or `[[linked-group]]` member written `cargo:foo` or `cargo/foo` resolves to package `foo` when a Cargo manifest declares `foo`, promoted or not, through the same selector resolver used for `--package` and changesets; a member naming an ecosystem with no such manifest fails loading with E108, and a bare member name ambiguous across ecosystems fails loading with E103 (not E108).",
      "is_error_case": true
    },
    {
      "id": "WS-ID-06",
      "criterion": "A changeset, `callisto add --package` or `callisto matrix --package` naming the bare name of promoted packages fails with E103 listing every qualified candidate and showing the qualified form to write; naming a package that does not exist under that name in that ecosystem fails with E102.",
      "is_error_case": true
    },
    {
      "id": "WS-ID-07",
      "criterion": "A dependency edge is created only to a workspace package that declares the dependency's name in the depending manifest's own ecosystem; a name declared only in other ecosystems creates no edge and one `unknown-package` warning listing the candidates (`cargo:foo`), and a name no workspace package declares creates no edge and no diagnostic."
    },
    {
      "id": "WS-ID-08",
      "criterion": "A package whose explicit `tag-template` equals another package's default tag template makes `status` and `version` fail with E101 naming both packages and the template.",
      "is_error_case": true
    },
    {
      "id": "WS-ID-09",
      "criterion": "A discovered package whose canonical manifests use different version grammars fails with E007 before version planning or init writes. This includes co-located Cargo.toml and pyproject.toml, whether the Python version is static or declared dynamic; matching numeric version strings do not bypass the grammar check.",
      "is_error_case": true
    },
    {
      "id": "WS-CFG-01",
      "criterion": "For each package, the first ecosystem-prefixed `[[package]]` rule whose ecosystem the package actually has a manifest in and whose name matches applies, regardless of declaration order relative to bare rules; a prefixed rule for an ecosystem the package has no manifest in never applies, even to a same-named package in another ecosystem. If no prefixed rule applies, the first matching bare rule applies."
    },
    {
      "id": "WS-CFG-03",
      "criterion": "A bare `[[package]]` rule that would apply to a promoted package fails loading with E103 listing the qualified candidates; prefixed rules for the same packages load normally.",
      "is_error_case": true
    },
    {
      "id": "WS-CFG-04",
      "criterion": "A `[[package-set]]` rule applies only when no `[[package]]` rule matches, the first matching set in declaration order wins, and a `cargo:`/`cargo/`, `npm:`/`npm/` or `pypi:`/`pypi/` prefix restricts it to packages with a manifest in that ecosystem."
    },
    {
      "id": "WS-CFG-05",
      "criterion": "A matched rule overrides only the fields it sets; otherwise a package uses release trigger `changeset`, `CHANGELOG.md` in its directory (a configured changelog is relative to the package directory), and the publish targets its manifests declare."
    },
    {
      "id": "WS-CFG-06",
      "criterion": "A `publish-to` override whose target ecosystem is not among the matched package's manifest ecosystems fails loading with E119.",
      "is_error_case": true
    },
    {
      "id": "WS-CFG-07",
      "criterion": "A `[[package-set]]` that matches no package emits one `package-set-matched-nothing` warning naming its pattern; a set matching a package that a `[[package]]` rule shadows counts as matched.",
      "is_error_case": true
    },
    {
      "id": "WS-CFG-08",
      "criterion": "A bare `[[package]]` rule matching packages whose manifests span two or more ecosystems, such as a dual-manifest package, emits one non-fatal `bare-rule-matches-multiple-ecosystems` warning; prefixed rules and `[[package-set]]` rules never emit it.",
      "is_error_case": true
    },
    {
      "id": "WS-CFG-09",
      "criterion": "A `[[package]]` rule that matches no package emits one `package-rule-matched-nothing` warning naming the rule.",
      "is_error_case": true
    },
    {
      "id": "WS-PLAT-01",
      "criterion": "A package.json with non-empty `os` and `cpu` arrays is an npm platform package whose platform and arch are the first entries; for Linux its ABI is `gnueabihf`, `gnu` or `musl` from the name's `-<abi>` suffix, otherwise none."
    },
    {
      "id": "WS-PLAT-02",
      "criterion": "An npm-only platform package named in the `optionalDependencies` of exactly one admitted npm package becomes an attached platform package of that owner, inside or outside the npm workspace globs: it is not its own package and adds no publish targets to the owner."
    },
    {
      "id": "WS-PLAT-03",
      "criterion": "A co-located platform manifest belongs to its directory's package, is never attached to another owner, and a `[[fixed-group]]` member may name any platform manifest by its own npm name."
    },
    {
      "id": "WS-PLAT-04",
      "criterion": "When an owner is versioned or snapshotted, each attached platform manifest receives the owner's new version and the owner's `optionalDependencies` pins update to it, with no fixed group required."
    },
    {
      "id": "WS-PLAT-05",
      "criterion": "An admitted platform package named in no owner's or several owners' `optionalDependencies` stays its own package and emits a `platform-package-without-owner` warning with its manifest path and the owner count or paths.",
      "is_error_case": true
    },
    {
      "id": "WS-PLAT-06",
      "criterion": "A platform package outside the npm workspace named by several owners emits `platform-package-without-owner` stating it is not released; one named by no owner stays undiscovered with no diagnostic.",
      "is_error_case": true
    }
  ],
  "spec_file_path": "docs/specs/workspace.json"
}

