#[derive(Clone, Debug, Default)]
pub struct IdentityIndex {
    pub bare: BTreeMap<String, PackageId>,
    pub prefixed: BTreeMap<(Ecosystem, String), PackageId>,
    pub native: BTreeMap<(Ecosystem, String), PackageId>,
    /// Keyed by a platform npm manifest's own package name (e.g.
    /// `"@myorg/my-crate-linux-x64-gnu"`) -- distinct from `owner`'s name
    /// when the owning package's primary identity comes from a
    /// higher-priority ecosystem sharing the same directory (a Cargo+npm
    /// dual project: platform manifests belong to the owning
    /// `Package`, they are never independently-registered `Package`s of
    /// their own). The `ManifestRole::Platform` is carried alongside so
    /// `GroupTable::resolve` doesn't need a second disk read to recover it.
    pub platform: BTreeMap<String, (PackageId, PathBuf, ManifestRole)>,
}

impl IdentityIndex {
    /// The one selector resolver: resolves a user- or config-typed package
    /// selector (`eco:name`, `eco/name`, or a bare name) against registered
    /// native manifest names.
    ///
    /// A qualified selector is an exact `(ecosystem, native name)` lookup: no
    /// match is `E102` ([`GraphError::UnknownPackage`]), regardless of what a
    /// different ecosystem calls itself. A bare selector searches every
    /// ecosystem's native names: no match is `E102`; more than one distinct
    /// package answering to that name in different ecosystems is `E103`
    /// ([`GraphError::AmbiguousName`]). Resolving by any registered native
    /// name -- not just a package's primary/display name -- is what lets a
    /// dual-manifest package be named by either of its manifests' names.
    pub fn resolve(&self, selector: &str) -> Result<PackageId, GraphError> {
        let id = PackageId::parse(selector).unwrap_or_else(|_| PackageId::Bare(selector.to_string()));
        self.resolve_id(&id)
    }

    /// [`Self::resolve`] for an already-parsed selector.
    pub fn resolve_id(&self, id: &PackageId) -> Result<PackageId, GraphError> {
        match id {
            PackageId::Prefixed { ecosystem, name } => self
                .native
                .get(&(*ecosystem, name.clone()))
                .cloned()
                .ok_or_else(|| GraphError::UnknownPackage { id: id.clone() }),
            PackageId::Bare(name) => {
                let candidates: BTreeSet<PackageId> = self
                    .native
                    .iter()
                    .filter(|((_, n), _)| n == name)
                    .map(|(_, registered)| registered.clone())
                    .collect();
                match candidates.len() {
                    0 => Err(GraphError::UnknownPackage { id: id.clone() }),
                    1 => Ok(candidates.into_iter().next().expect("len checked above")),
                    _ => Err(GraphError::AmbiguousName {
                        name: name.clone(),
                        candidates: candidates.into_iter().collect(),
                    }),
                }
            }
        }
    }

    /// True when `selector` (an ecosystem-qualified or bare configured
    /// package identity, e.g. from `[[release.artifact]]` or
    /// `product-package`) resolves to `candidate`.
    ///
    /// The single replacement for the `selector.matches(&candidate) &&
    /// selector.ecosystem() == Some(candidate_ecosystem)` guard that was
    /// hand-rolled at every config-selector call site: `PackageId::matches`
    /// alone treats a bare id as an ecosystem wildcard, so a qualified
    /// selector for one ecosystem's package would otherwise match a
    /// same-named package in another.
    pub fn identifies(&self, selector: &PackageId, candidate: &PackageId) -> bool {
        self.resolve_id(selector).is_ok_and(|resolved| &resolved == candidate)
    }

    pub fn resolve_human(&self, name: &str, siblings: &[PackageId]) -> Result<PackageId, GraphError> {
        if let Ok(PackageId::Prefixed { ecosystem, name: n }) = PackageId::parse(name) {
            if let Some(id) = self.prefixed.get(&(ecosystem, n)) {
                return Ok(id.clone());
            }
        }

        if let Some(id) = self.bare.get(name) {
            return Ok(id.clone());
        }

        let mut candidates = Vec::new();
        for ((_eco, n), id) in &self.prefixed {
            if n == name {
                candidates.push(id.clone());
            }
        }

        if candidates.len() == 1 {
            return Ok(candidates[0].clone());
        }

        if candidates.len() > 1 && !siblings.is_empty() {
            for sib in siblings {
                for cand in &candidates {
                    if cand.ecosystem() == sib.ecosystem() {
                        return Ok(cand.clone());
                    }
                }
            }
        }

        if candidates.is_empty() {
            Err(GraphError::UnknownPackage {
                id: PackageId::parse(name).unwrap_or_else(|_| PackageId::Bare(name.to_string())),
            })
        } else {
            Err(GraphError::AmbiguousName {
                name: name.to_string(),
                candidates,
            })
        }
    }

    /// Look up a package by its native (manifest-declared) name.
    ///
    /// Python names use PEP 503 equivalence; other ecosystems use exact names.
    /// If no name matches within the ecosystem -- a
    /// package in one ecosystem depending on a different ecosystem's
    /// package by bare name (e.g. an npm package listing a cargo crate)
    /// -- falls back to scanning all ecosystems for `name`.
    ///
    /// Fallback finds exactly one match: returns it. Finds more than one
    /// (two ecosystems both have `name`): returns `None` to prevent
    /// silent misresolution -- callers holding a `&mut Vec<Diagnostic>`
    /// should use [`Self::resolve_native_with_fallback`] instead, to get
    /// a diagnostic.
    pub fn resolve_native(&self, eco: Ecosystem, name: &str) -> Option<&PackageId> {
        match self.native_in_ecosystem(eco, name) {
            Ok(Some(id)) => return Some(id),
            Ok(None) => {}
            Err(_) => return None,
        }

        // Cross-ecosystem fallback.
        let mut candidates: Vec<&PackageId> = self
            .native
            .iter()
            .filter(|((e, n), _)| *e != eco && n == name)
            .map(|(_, id)| id)
            .collect();

        // Deduplicate by pointer identity (multiple entries for the same ID
        // across different ecosystems, e.g. a package that is both cargo and
        // npm, should not be treated as ambiguous).
        candidates.dedup_by(|a, b| a == b);

        match candidates.len() {
            1 => Some(candidates[0]),
            // 0 = not found; >1 = true ambiguity → caller should diagnose.
            _ => None,
        }
    }

    /// Resolves within the declaring ecosystem, using PEP 503 equivalence for Python.
    /// Ambiguous Python names and cross-ecosystem candidates produce a warning and no match.
    pub fn resolve_native_with_fallback<'a>(
        &'a self,
        eco: Ecosystem,
        name: &str,
        diagnostics: &mut Vec<callisto_model::Diagnostic>,
    ) -> Option<&'a PackageId> {
        match self.native_in_ecosystem(eco, name) {
            Ok(Some(id)) => return Some(id),
            Ok(None) => {}
            Err(error) => {
                diagnostics.push(callisto_model::Diagnostic {
                    code: callisto_model::DiagnosticCode::UnknownPackage,
                    severity: callisto_model::DiagnosticSeverity::Warning,
                    message: error.to_string(),
                    package: None,
                    path: None,
                    escalated_by: None,
                    governed_by: None,
                });
                return None;
            }
        }

        // Cross-ecosystem fallback: collect unique IDs from other ecosystems,
        // keeping each candidate's own native name (`n`, the map key) rather
        // than its owning package's primary name (`id.name()`) -- a
        // dual-manifest package's manifests can declare different names, and
        // the diagnostic must name what the *other* ecosystem actually calls
        // it, not this package's unrelated primary/display name.
        let mut candidates: Vec<(Ecosystem, &str, &PackageId)> = self
            .native
            .iter()
            .filter(|((e, n), _)| *e != eco && n == name)
            .map(|((e, n), id)| (*e, n.as_str(), id))
            .collect();
        candidates.dedup_by(|a, b| a.2 == b.2);

        match candidates.len() {
            0 => None,
            _ => {
                let candidate_names: Vec<String> = candidates
                    .iter()
                    .map(|(e, n, _)| format!("{}:{n}", e.prefix()))
                    .collect();
                diagnostics.push(callisto_model::Diagnostic {
                    code: callisto_model::DiagnosticCode::UnknownPackage,
                    severity: callisto_model::DiagnosticSeverity::Warning,
                    // No ecosystem-prefix advice here: this name comes from a
                    // manifest's own dependency field, which cannot carry an
                    // `eco:name` prefix -- the ambiguity can only be resolved
                    // by renaming one of the candidates.
                    message: format!(
                        "dependency name `{name}` is ambiguous across ecosystems: {}",
                        candidate_names.join(", "),
                    ),
                    package: None,
                    path: None,
                    escalated_by: None,
                    governed_by: None,
                });
                None
            }
        }
    }

    fn native_in_ecosystem(&self, eco: Ecosystem, name: &str) -> Result<Option<&PackageId>, GraphError> {
        if eco != Ecosystem::Pypi {
            return Ok(self.native.get(&(eco, name.to_string())));
        }

        let normalized = normalize_pypi_project_name(name);
        let candidates: BTreeSet<&PackageId> = self
            .native
            .iter()
            .filter(|((ecosystem, native_name), _)| {
                *ecosystem == eco && normalize_pypi_project_name(native_name) == normalized
            })
            .map(|(_, id)| id)
            .collect();
        match candidates.len() {
            0 => Ok(None),
            1 => Ok(candidates.into_iter().next()),
            _ => Err(GraphError::AmbiguousName {
                name: name.to_string(),
                candidates: candidates.into_iter().cloned().collect(),
            }),
        }
    }

    pub fn native_name(&self, id: &PackageId, eco: Ecosystem) -> Option<&str> {
        for ((e, name), registered_id) in &self.native {
            if e == &eco && registered_id == id {
                return Some(name.as_str());
            }
        }
        None
    }

    pub fn native_names(&self, id: &PackageId) -> impl Iterator<Item = (Ecosystem, &str)> {
        let mut results = Vec::new();
        for ((e, name), registered_id) in &self.native {
            if registered_id == id {
                results.push((*e, name.as_str()));
            }
        }
        results.into_iter()
    }

    pub fn display_form(&self, id: &PackageId) -> String {
        id.display_name()
    }

    /// The platform manifests attached to `owner` from their own
    /// directories, as (npm name, manifest path). Excludes a co-located platform
    /// manifest that is also one of `owner`'s canonical manifests.
    pub fn attached_platforms<'a>(
        &'a self,
        owner: &'a callisto_model::Package,
    ) -> impl Iterator<Item = (&'a str, &'a Path)> + 'a {
        self.platforms_of(&owner.id)
            .filter(|(_, path)| !owner.canonical_manifests().any(|m| m.path == *path))
    }

    pub fn platforms_of(&self, owner: &PackageId) -> impl Iterator<Item = (&str, &Path)> {
        let mut results = Vec::new();
        for (name, (plat_owner, path, _role)) in &self.platform {
            if plat_owner == owner {
                results.push((name.as_str(), path.as_path()));
            }
        }
        results.into_iter()
    }
}
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

use crate::{ManifestFormat, NpmAccess, RegistryKey, VersionGrammar};

/// Ecosystem supported by callisto.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
#[non_exhaustive]
pub enum Ecosystem {
    Cargo,
    Npm,
    // Demand-gated ecosystems:
    Pypi,
    Go,
    Maven,
    NuGet,
    Deno,
    Jsr,
}

impl Ecosystem {
    /// The three ecosystems package *identity discovery* treats as
    /// canonical -- each has exactly one manifest format
    /// ([`Ecosystem::canonical_manifest_format`]) that carries a package's
    /// name and (usually) version. Deliberately excludes the other,
    /// demand-gated ecosystems in this enum (Go, Maven, NuGet, ...), which
    /// either have no canonical-identity manifest wired up yet or aren't
    /// part of this duplication (see audit pattern B).
    pub const CANONICAL: [Ecosystem; 3] = [Ecosystem::Cargo, Ecosystem::Npm, Ecosystem::Pypi];

    /// The manifest format that carries this ecosystem's package identity
    /// (name and version), for the [`Self::CANONICAL`] ecosystems only.
    /// `None` for every other ecosystem in this enum.
    pub fn canonical_manifest_format(&self) -> Option<ManifestFormat> {
        match self {
            Ecosystem::Cargo => Some(ManifestFormat::CargoToml),
            Ecosystem::Npm => Some(ManifestFormat::PackageJson),
            Ecosystem::Pypi => Some(ManifestFormat::PyprojectToml),
            _ => None,
        }
    }

    pub fn prefix(&self) -> &'static str {
        match self {
            Ecosystem::Cargo => "cargo",
            Ecosystem::Npm => "npm",
            Ecosystem::Pypi => "pypi",
            Ecosystem::Go => "go",
            Ecosystem::Maven => "maven",
            Ecosystem::NuGet => "nuget",
            Ecosystem::Deno => "deno",
            Ecosystem::Jsr => "jsr",
        }
    }

    pub fn from_prefix(s: &str) -> Option<Self> {
        match s.to_ascii_lowercase().as_str() {
            "cargo" => Some(Ecosystem::Cargo),
            "npm" => Some(Ecosystem::Npm),
            "pypi" => Some(Ecosystem::Pypi),
            "go" => Some(Ecosystem::Go),
            "maven" => Some(Ecosystem::Maven),
            "nuget" => Some(Ecosystem::NuGet),
            "deno" => Some(Ecosystem::Deno),
            "jsr" => Some(Ecosystem::Jsr),
            _ => None,
        }
    }

    pub fn version_grammar(&self) -> VersionGrammar {
        match self {
            Ecosystem::Cargo | Ecosystem::Npm | Ecosystem::Deno | Ecosystem::Jsr | Ecosystem::NuGet | Ecosystem::Go => {
                VersionGrammar::SemVer
            }
            Ecosystem::Pypi => VersionGrammar::Pep440,
            Ecosystem::Maven => VersionGrammar::Maven,
        }
    }

    pub fn is_implemented(&self) -> bool {
        matches!(self, Ecosystem::Cargo | Ecosystem::Npm | Ecosystem::Pypi)
    }
}

/// Target registry or release location.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
#[non_exhaustive]
pub enum PublishTarget {
    CratesIo,
    Npm {
        registry: Option<String>,
        /// The operator's explicit `publishConfig.access` from `package.json`,
        /// if set. `None` means npm's `publishConfig.access` was absent --
        /// distinct from an explicit `"public"`, which a bare bool couldn't
        /// represent (both collapsed to `false`, silently dropping an
        /// unscoped package's explicit `"public"` setting). When `Some`,
        /// release planning passes the corresponding `--access` flag rather
        /// than falling back to the `@scope/name`-implies-public heuristic.
        access: Option<NpmAccess>,
    },
    Pypi {
        index: Option<String>,
    },
    NuGet {
        source: Option<String>,
    },
    GitHubRelease,
    None,
}

impl PublishTarget {
    pub fn registry_key(&self) -> Option<RegistryKey> {
        match self {
            PublishTarget::CratesIo => Some(RegistryKey(RegistryKey::CRATES_IO.to_string())),
            PublishTarget::Npm { .. } => Some(RegistryKey(RegistryKey::NPM.to_string())),
            PublishTarget::Pypi { .. } => Some(RegistryKey(RegistryKey::PYPI.to_string())),
            PublishTarget::NuGet { .. } => Some(RegistryKey(RegistryKey::NUGET.to_string())),
            PublishTarget::GitHubRelease | PublishTarget::None => None,
        }
    }

    pub fn ecosystem(&self) -> Option<Ecosystem> {
        match self {
            PublishTarget::CratesIo => Some(Ecosystem::Cargo),
            PublishTarget::Npm { .. } => Some(Ecosystem::Npm),
            PublishTarget::Pypi { .. } => Some(Ecosystem::Pypi),
            PublishTarget::NuGet { .. } => Some(Ecosystem::NuGet),
            PublishTarget::GitHubRelease | PublishTarget::None => None,
        }
    }

    /// The `publish-to` config string this variant parses from, mirroring
    /// `parse_publish_target` in `callisto_graph::config::resolve`. Used to
    /// name the mismatched target in diagnostics/errors without leaking the
    /// `Debug` representation of the variant's payload, and doubles as the
    /// semantic-fingerprint "kind" string (`target_fingerprint` in
    /// `callisto_graph::commands::release`) since both need the exact same
    /// stable, variant-identifying string.
    pub fn config_str(&self) -> &'static str {
        match self {
            PublishTarget::CratesIo => "crates-io",
            PublishTarget::Npm { .. } => "npm",
            PublishTarget::Pypi { .. } => "pypi",
            PublishTarget::NuGet { .. } => "nuget",
            PublishTarget::GitHubRelease => "github-release",
            PublishTarget::None => "none",
        }
    }

    /// The operator's explicit registry/index/source override carried by
    /// this variant's payload, if any -- `Npm.registry`, `Pypi.index`, and
    /// `NuGet.source` are all "the same field" for this purpose. `CratesIo`,
    /// `GitHubRelease`, and `None` carry no such override.
    pub fn registry_override(&self) -> Option<&str> {
        match self {
            PublishTarget::Npm { registry, .. } => registry.as_deref(),
            PublishTarget::Pypi { index } => index.as_deref(),
            PublishTarget::NuGet { source } => source.as_deref(),
            PublishTarget::CratesIo | PublishTarget::GitHubRelease | PublishTarget::None => None,
        }
    }

    /// Fills gaps left by a `[[package]]`/`[[package-set]]` `publish-to`
    /// override with the manifest-derived target for the same ecosystem --
    /// e.g. npm's `publishConfig.access`/`registry`, which an override
    /// naming only `"npm"` doesn't itself specify. Fields the override
    /// *does* set are never touched: config wins when explicit, the
    /// manifest only fills what the override left blank. Other ecosystems
    /// (`Pypi.index`, `NuGet.source`) have no manifest reader populating
    /// them yet, so there is nothing to fill in for them today.
    pub fn merge_manifest_gaps(self, manifest_derived: &PublishTarget) -> PublishTarget {
        match (self, manifest_derived) {
            (
                PublishTarget::Npm { registry, access },
                PublishTarget::Npm {
                    registry: manifest_registry,
                    access: manifest_access,
                },
            ) => PublishTarget::Npm {
                registry: registry.or_else(|| manifest_registry.clone()),
                access: access.or(*manifest_access),
            },
            (target, _) => target,
        }
    }

    /// Whether this target has a real dispatch implementation today.
    ///
    /// `PublishTarget` and `Ecosystem` are not 1:1: `GitHubRelease` is a VCS
    /// release action with no backing package `Ecosystem` (the release path
    /// dispatches it), and `None` is the "not configured to publish" sentinel,
    /// not a real target -- neither can defer to `Ecosystem::is_implemented()`. Every other
    /// variant carries a package ecosystem ([`Self::ecosystem`]) and defers
    /// to that ecosystem's own implementedness.
    pub fn is_implemented(&self) -> bool {
        match self {
            PublishTarget::None | PublishTarget::GitHubRelease => true,
            PublishTarget::CratesIo
            | PublishTarget::Npm { .. }
            | PublishTarget::Pypi { .. }
            | PublishTarget::NuGet { .. } => self.ecosystem().is_some_and(|ecosystem| ecosystem.is_implemented()),
        }
    }
}

/// PEP 503 / PEP 427 style Python package-name normalization: lowercase,
/// then collapse any run of hyphens, dots, or underscores into a single
/// underscore. This makes name-equality comparisons and wheel-filename
/// construction agree that "my-package", "my_package", "my.package", and
/// "My--Package" all refer to the same PyPI distribution -- PEP 503's own
/// canonicalization rule (`re.sub(r"[-_.]+", "-", name).lower()`), joined
/// with `_` to match PEP 427's wheel-filename escaping instead of PEP
/// 503's own `-` (the join character doesn't affect equality comparisons,
/// only which convention a caller building a filename needs).
pub fn normalize_pypi_package_name(name: &str) -> String {
    pypi_name_parts(name).join("_")
}

/// The PEP 503 normalized project name: the same equivalence, joined with
/// hyphens, which is the form PyPI's own URLs use.
pub fn normalize_pypi_project_name(name: &str) -> String {
    pypi_name_parts(name).join("-")
}

fn pypi_name_parts(name: &str) -> Vec<String> {
    name.to_lowercase()
        .split(['-', '.', '_'])
        .filter(|part| !part.is_empty())
        .map(ToOwned::to_owned)
        .collect()
}

/// Trigger mechanism for generating releases.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum ReleaseTrigger {
    #[default]
    Changeset,
    Auto,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn maps_ecosystem_prefixes() {
        assert_eq!(Ecosystem::from_prefix("cargo"), Some(Ecosystem::Cargo));
        assert_eq!(Ecosystem::from_prefix("npm"), Some(Ecosystem::Npm));
        assert_eq!(Ecosystem::Cargo.prefix(), "cargo");
    }

    #[test]
    fn identifies_implemented_ecosystems() {
        assert!(Ecosystem::Cargo.is_implemented());
        assert!(Ecosystem::Npm.is_implemented());
        assert!(Ecosystem::Pypi.is_implemented());
    }

    #[test]
    fn canonical_ecosystems_each_have_a_canonical_manifest_format() {
        assert_eq!(Ecosystem::CANONICAL.len(), 3);
        assert_eq!(
            Ecosystem::Cargo.canonical_manifest_format(),
            Some(ManifestFormat::CargoToml)
        );
        assert_eq!(
            Ecosystem::Npm.canonical_manifest_format(),
            Some(ManifestFormat::PackageJson)
        );
        assert_eq!(
            Ecosystem::Pypi.canonical_manifest_format(),
            Some(ManifestFormat::PyprojectToml)
        );
    }

    #[test]
    fn non_canonical_ecosystems_have_no_canonical_manifest_format() {
        assert_eq!(Ecosystem::Go.canonical_manifest_format(), None);
        assert_eq!(Ecosystem::Maven.canonical_manifest_format(), None);
        assert_eq!(Ecosystem::NuGet.canonical_manifest_format(), None);
        assert_eq!(Ecosystem::Deno.canonical_manifest_format(), None);
        assert_eq!(Ecosystem::Jsr.canonical_manifest_format(), None);
    }

    #[test]
    fn normalize_pypi_package_name_treats_hyphen_underscore_dot_as_equivalent() {
        assert_eq!(normalize_pypi_package_name("my-package"), "my_package");
        assert_eq!(normalize_pypi_package_name("my_package"), "my_package");
        assert_eq!(normalize_pypi_package_name("my.package"), "my_package");
        assert_eq!(normalize_pypi_package_name("My--Package"), "my_package");
        assert_eq!(normalize_pypi_package_name("MY.PACKAGE"), "my_package");
        assert_eq!(normalize_pypi_project_name("My--Package"), "my-package");
        assert_eq!(normalize_pypi_project_name("MY.PACKAGE"), "my-package");
    }

    #[test]
    fn normalize_pypi_package_name_collapses_mixed_runs() {
        assert_eq!(normalize_pypi_package_name("foo-.-bar"), "foo_bar");
        assert_eq!(normalize_pypi_package_name("foo___bar"), "foo_bar");
    }

    #[test]
    fn publish_target_registry_override_extracts_payload_field() {
        assert_eq!(PublishTarget::CratesIo.registry_override(), None);
        assert_eq!(
            PublishTarget::Npm {
                registry: Some("https://npm.example.com".to_string()),
                access: None
            }
            .registry_override(),
            Some("https://npm.example.com")
        );
        assert_eq!(
            PublishTarget::Npm {
                registry: None,
                access: None
            }
            .registry_override(),
            None
        );
        assert_eq!(
            PublishTarget::Pypi {
                index: Some("https://pypi.example.com".to_string())
            }
            .registry_override(),
            Some("https://pypi.example.com")
        );
        assert_eq!(
            PublishTarget::NuGet {
                source: Some("https://nuget.example.com".to_string())
            }
            .registry_override(),
            Some("https://nuget.example.com")
        );
        assert_eq!(PublishTarget::GitHubRelease.registry_override(), None);
        assert_eq!(PublishTarget::None.registry_override(), None);
    }

    #[test]
    fn publish_target_is_implemented_matches_dispatchable_variants() {
        assert!(PublishTarget::CratesIo.is_implemented());
        assert!(PublishTarget::Npm {
            registry: None,
            access: None
        }
        .is_implemented());
        assert!(PublishTarget::Pypi { index: None }.is_implemented());
        assert!(!PublishTarget::NuGet { source: None }.is_implemented());
        assert!(PublishTarget::GitHubRelease.is_implemented());
        // `None` is vacuously "implemented" -- there is nothing to dispatch,
        // so it must never trip a `PublishTargetNotImplemented` diagnostic.
        assert!(PublishTarget::None.is_implemented());
    }
}

